1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import {
4	    revokeAgent,
5	    getAgentAudit,
6	    type AgentSummary,
7	    type AgentAuditEvent,
8	  } from '$lib/ipc';
9	  import { authenticateBiometric } from '$lib/biometric';
10	  import { describeScopes } from '$lib/agent-scopes';
11	  import {
12	    AGENT_STATUS,
13	    AGENT_EVENT_LABELS,
14	    AGENT_TYPE_LABELS,
15	    agentName,
16	    agentDetailLine,
17	  } from '$lib/agent-display';
18	  import { formatTimestamp } from '$lib/datetime';
19	  import Button from '$lib/components/ui/Button.svelte';
20	  import Spinner from '$lib/components/ui/Spinner.svelte';
21	  import ScreenHeader from '$lib/components/ui/ScreenHeader.svelte';
22	
23	  let {
24	    agent,
25	    onback,
26	    onrevoked,
27	  }: {
28	    agent: AgentSummary;
29	    onback: () => void;
30	    /** Tell the parent list this agent is now revoked, so its card reflects the new status. */
31	    onrevoked: (registrationId: string) => void;
32	  } = $props();
33	
34	  // This component's lifetime is the selection, so no cross-agent stale-guards are needed: an
35	  // audit/revoke request in flight when the user navigates back simply resolves into an unmounted
36	  // component. Status is the only field that changes here — a successful revoke sets the local
37	  // override, and the displayed status derives from it over the incoming prop.
38	  let revokedLocally = $state(false);
39	  let status = $derived(revokedLocally ? 'revoked' : agent.status);
40	
41	  let auditEvents = $state<AgentAuditEvent[]>([]);
42	  let auditCursor = $state<string | undefined>(undefined);
43	  let auditLoading = $state(false);
44	  let auditError = $state<string | null>(null);
45	
46	  // Revocation flow: explicit confirm step, then biometric.
47	  let confirmingRevoke = $state(false);
48	  let revoking = $state(false);
49	  let revokeError = $state<string | null>(null);
50	
51	  let currentStatus = $derived(AGENT_STATUS[status]);
52	
53	  async function loadMoreAudit() {
54	    const cursor = auditCursor;
55	    auditLoading = true;
56	    auditError = null;
57	    try {
58	      const page = await getAgentAudit(agent.registrationId, cursor);
59	      auditEvents = [...auditEvents, ...page.events];
60	      auditCursor = page.cursor;
61	    } catch (e) {
62	      console.error('Failed to load audit trail:', e);
63	      auditError = 'Could not load the activity record.';
64	    } finally {
65	      auditLoading = false;
66	    }
67	  }
68	
69	  async function doRevoke() {
70	    if (revoking) return;
71	    revokeError = null;
72	    // Set the in-flight flag before the biometric prompt so a second tap during the Face ID
73	    // wait cannot fire a duplicate prompt/revocation.
74	    revoking = true;
75	    try {
76	      await authenticateBiometric('Revoke this agent’s access');
77	    } catch {
78	      revoking = false;
79	      return; // gate rejected — nothing changes.
