1	<script lang="ts">
2	  import ChevronLeftIcon from '$lib/components/ui/ChevronLeftIcon.svelte';
3	  import { isDidWeb } from '$lib/did-doc-utils';
4	
5	  let {
6	    didDoc,
7	    onback,
8	    onmigrate,
9	    onchangehandle,
10	    onremove,
11	  }: {
12	    didDoc: Record<string, unknown>;
13	    onback: () => void;
14	    /** Only passed when the device key is the DID's root rotation key — gates the
15	     *  wallet-authorized outbound migration entry point (ADR-0002 path 1). */
16	    onmigrate?: () => void;
17	    /** Only passed for a wallet-custodied did:plc (device key in the rotation set) —
18	     *  gates the sovereign change-handle entry point (device-key-signed alsoKnownAs op). */
19	    onchangehandle?: () => void;
20	    /** Opens the permanent-removal flow (delete on PDS + tombstone DID + local wipe). */
21	    onremove?: () => void;
22	  } = $props();
23	
24	  // A did:web identity has no PLC machinery (ADR-0003): no rotation-key hierarchy, no public audit
25	  // log, no recovery window. We say so plainly rather than presenting the wallet's PLC-only
26	  // assurances (monitoring, recovery, the claim/Shamir ceremonies) as if they applied.
27	  let isWebDid = $derived(typeof didDoc.id === 'string' && isDidWeb(didDoc.id));
28	
29	  let showRaw = $state(false);
30	  let copiedKeyId = $state<string | null>(null);
31	  let failedKeyId = $state<string | null>(null);
32	
33	  // Extract typed arrays from the loosely-typed didDoc.
34	  let verificationMethods = $derived(
35	    Array.isArray(didDoc.verificationMethod)
36	      ? (didDoc.verificationMethod as Array<Record<string, unknown>>)
37	      : []
38	  );
39	
40	  let alsoKnownAs = $derived(
41	    Array.isArray(didDoc.alsoKnownAs)
42	      ? (didDoc.alsoKnownAs as Array<string>)
43	      : []
44	  );
45	
46	  let services = $derived(
47	    Array.isArray(didDoc.service)
48	      ? (didDoc.service as Array<Record<string, unknown>>)
49	      : []
50	  );
51	
52	  let rawJson = $derived(JSON.stringify(didDoc, null, 2));
53	
54	  async function copyKey(keyId: string, value: string) {
55	    try {
56	      await navigator.clipboard.writeText(value);
57	      copiedKeyId = keyId;
58	      setTimeout(() => { copiedKeyId = null; }, 2000);
59	    } catch {
60	      failedKeyId = keyId;
61	      setTimeout(() => { failedKeyId = null; }, 2000);
62	    }
63	  }
64	</script>
