68	    <ChevronLeftIcon />
69	    Back
70	  </button>
71	  <h1 class="title">DID document</h1>
72	
73	  {#if isWebDid}
74	    <div class="didweb" role="note">
75	      <span class="didweb-ic" aria-hidden="true">
76	        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>
77	      </span>
78	      <div class="didweb-body">
79	        <p class="didweb-t">This is a did:web identity</p>
80	        <p class="didweb-s">
81	          Its DID document lives at a domain you control — not on the public PLC directory. The
82	          wallet's PLC protections don't apply here: there is <strong>no rotation-key hierarchy</strong>,
83	          <strong>no public audit log to monitor</strong>, and <strong>no 72-hour recovery window</strong>.
84	          This identity is defended by control of its domain, so keep the domain and its
85	          <code>did.json</code> secure. To move it to another PDS, edit that <code>did.json</code>
86	          yourself — there is no PLC operation to sign.
87	        </p>
88	      </div>
89	    </div>
90	  {/if}
91	
92	  <div class="section">
