119	              >
120	                {copiedKeyId === String(method.id) ? 'Copied!' : failedKeyId === String(method.id) ? 'Failed' : 'Copy'}
121	              </button>
122	            </div>
123	          {/if}
124	        </div>
125	      {/each}
126	    </div>
127	  {/if}
128	
