/// Mint a fresh ES256 service-auth JWT for proxying `nsid` to `proxy_did` on behalf of `did`.
///
/// Delegates the key load + claim assembly to the shared
/// [`crate::auth::signing_key::mint_account_service_auth`] (the same path
/// `com.atproto.server.getServiceAuth` uses) so the two never drift. Resolves the master key and
/// strips the audience fragment here: `aud` = the service DID with any `#fragment` removed (the
/// AppView keys verification on the bare DID; the fragment belongs in the `atproto-proxy` header),
/// `lxm` = the proxied method, 60s TTL. Returns the built error response on the unhappy paths
/// (master key missing → 503, clock failure → 500, key load/decrypt failure → 500).
pub(crate) async fn mint_service_auth(
    state: &AppState,
    did: &str,
    proxy_did: &str,
    nsid: &str,
) -> Result<String, Response> {
    use std::time::{SystemTime, UNIX_EPOCH};

    let master_key: &[u8; 32] = state
        .config
        .signing_key_master_key
        .as_ref()
        .map(|s| &*s.0)
        .ok_or_else(|| {
            ApiError::new(
                ErrorCode::ServiceUnavailable,
                "signing key master key not configured",
            )
            .into_response()
        })?;

    // The audience is the bare service DID — a `#fragment` (e.g. `#bsky_chat`) belongs in the
    // `atproto-proxy` header, not the JWT `aud`, which the AppView matches against its own DID.
    let aud = proxy_did.split('#').next().unwrap_or(proxy_did);

    // Mint with the same clock-failure handling as getServiceAuth (a 500), rather than silently
    // emitting an already-expired token.
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .map_err(|_| {
            ApiError::new(ErrorCode::InternalError, "system clock error").into_response()
        })?;

    crate::auth::signing_key::mint_account_service_auth(
        &state.db,
        master_key,
        did,
        aud,
        Some(nsid),
        now,
        now + 60,
    )
    .await
    .map_err(IntoResponse::into_response)
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;

    use axum::{
        body::Body,
        http::{Request, StatusCode},
    };
    use tower::ServiceExt;
    use wiremock::matchers::{body_json, header, header_exists, method, path, query_param};
    use wiremock::{Mock, MockServer, ResponseTemplate};

    use crate::app::{app, test_state, AppState};
    use crate::routes::test_utils::test_master_key;

    /// The account DID baked into every proxied request's bearer token (see [`bearer`]). The
    /// proxy mints the service-auth JWT for whichever DID the inbound session authenticates as,
    /// so this is the DID we must seed a repo signing key for.
    const TEST_DID: &str = "did:plc:tester";

    /// Seed `TEST_DID` with an account row and a per-account repo signing key, encrypted under
    /// [`test_master_key`]. The proxy needs only the *decryptable signing key* to mint the
    /// service-auth JWT — not a full repo — so this is leaner than `seed_account_with_repo`.

// pattern: Imperative Shell

//! Per-account ATProto repo signing key queries.
//!
//! The key is generated during the DID ceremony and stored on the pending
//! account (`pending_accounts.repo_signing_*`), then copied into `signing_keys`
//! (DID-keyed) inside the promotion transaction. The private key is always
//! AES-256-GCM encrypted by the caller before it reaches these functions —
//! this module only moves opaque ciphertext, never plaintext key material.

#![allow(dead_code)]

use sqlx::{Sqlite, SqlitePool};

/// A repo signing key as stored: did:key id, multibase public key, and the
/// AES-256-GCM-encrypted private key (80-char base64, per `crypto::encrypt_private_key`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RepoSigningKey {
    pub key_id: String,
    pub public_key: String,
    pub private_key_encrypted: String,
}

/// Store the generated per-account repo signing key on the pending account.
/// Overwrites any existing key for the pending account (the ceremony endpoint
/// is idempotent and reuses the existing key, so this only writes once).
pub async fn set_pending_repo_key(
    pool: &SqlitePool,
    account_id: &str,
    key: &RepoSigningKey,
) -> Result<(), sqlx::Error> {
    sqlx::query(
        "UPDATE pending_accounts \
         SET repo_signing_key_id = ?, repo_signing_public_key = ?, \
             repo_signing_private_key_encrypted = ? \
         WHERE id = ?",
    )
    .bind(&key.key_id)
    .bind(&key.public_key)
    .bind(&key.private_key_encrypted)
    .bind(account_id)
    .execute(pool)
    .await?;
    Ok(())
}

/// Fetch the per-account repo signing key from the pending account.
/// Returns `None` if no key has been generated yet (all three columns NULL).
pub async fn get_pending_repo_key(
    pool: &SqlitePool,
    account_id: &str,
) -> Result<Option<RepoSigningKey>, sqlx::Error> {
    let row: Option<(Option<String>, Option<String>, Option<String>)> = sqlx::query_as(
        "SELECT repo_signing_key_id, repo_signing_public_key, \
                repo_signing_private_key_encrypted \
         FROM pending_accounts WHERE id = ?",
    )
    .bind(account_id)
    .fetch_optional(pool)
    .await?;

